import { Prism, languages } from '../prismCore'
import './markup'

/**
 * Returns the placeholder for the given language id and index.
 *
 * @param {string} language
 * @param {string|number} index
 * @returns {string}
 */
var getPlaceholder = (language, index) =>
	'___' + language.toUpperCase() + index + '___';

Object.defineProperties(languages['markup-templating'] = {}, {
	buildPlaceholders: {
		/**
		 * Tokenize all inline templating expressions matching `placeholderPattern`.
		 *
		 * If `replaceFilter` is provided, only matches of `placeholderPattern` for which `replaceFilter` returns
		 * `true` will be replaced.
		 *
		 * @param {object} env The environment of the `before-tokenize` hook.
		 * @param {string} language The language id.
		 * @param {RegExp} placeholderPattern The matches of this pattern will be replaced by placeholders.
		 * @param {(match: string) => boolean} [replaceFilter]
		 */
		value(env, language, placeholderPattern, replaceFilter) {
			if (env.language != language) {
				return;
			}

			var tokenStack = env.tokenStack = [];
			var code = env.code;

			env.code = code.replace(placeholderPattern, match => {
				if (replaceFilter && !replaceFilter(match)) {
					return match;
				}
				var i = tokenStack.length;
				var placeholder;

				// Check for existing strings
				while (code.indexOf(placeholder = getPlaceholder(language, i)) + 1) {
					++i;
				}

				// Create a sparse array
				tokenStack[i] = match;

				return placeholder;
			});

			// Switch the grammar to markup
			env.grammar = languages.markup;
		}
	},
	tokenizePlaceholders: {
		/**
		 * Replace placeholders with proper tokens after tokenizing.
		 *
		 * @param {object} env The environment of the `after-tokenize` hook.
		 * @param {string} language The language id.
		 */
		value(env, language) {
			if (env.language != language || !env.tokenStack) {
				return;
			}

			// Switch the grammar back
			env.grammar = languages[language];

			var j = 0;
			var keys = Object.keys(env.tokenStack);
			var l = keys.length;
			var parentCount = 0;
			var parents = [];

			var walkTokens = tokens => {
				for (var i = 0; i < tokens.length && j < l; i++) {
					var token = tokens[i];
					var content = token.content;

					if (content) parents[parentCount++] = token;
					if (Array.isArray(content)) {
						walkTokens(content);
					}
					else {
						var k = keys[j];
						var t = env.tokenStack[k];
						var s = content || token;
						var placeholder = getPlaceholder(language, k);

						var index = s.indexOf(placeholder);
						if (index + 1) {
							++j;

							var before = s.slice(0, index);
							var length = placeholder.length;
							var middle = new Prism.Token(language, Prism.tokenize(t, env.grammar), 'language-' + language, t);
							var after = s.slice(index + length);

							var replacement = [];
							var m = 0;
							if (before) {
								replacement.push(...walkTokens([before]));
							}
							replacement.push(middle);
							if (after) {
								replacement.push(...walkTokens([after]));
							}
							for (; m < parentCount; ) parents[m++].length += t.length - length;

							if (!content) {
								tokens.splice(i, 1, ...replacement);
							} else {
								token.content = replacement;
							}
						}
					}
					if (content) parentCount--;
				}

				return tokens;
			}

			walkTokens(env.tokens);
		}
	}
});
